// WRONG: Resource leak - file descriptor never released if exception occurs
public String readConfigBad(String filename) {
    BufferedReader reader = null;
    try {
        reader = Files.newBufferedReader(Path.of(filename));
        return reader.readLine();  // exception here leaks the reader
    } catch (IOException e) {
        return "default-value";  // reader never closed!
    }
}

// CORRECT: try-with-resources guarantees closure
public String readConfigGood(String filename) {
    try (var reader = Files.newBufferedReader(Path.of(filename))) {
        return reader.readLine();
    } catch (IOException e) {
        return "default-value";  // reader automatically closed before catch
    }
}

// Multiple resources - closed in reverse order
public void copyFileWithLogging(Path source, Path target, Path logFile) throws IOException {
    try (var input = Files.newInputStream(source);
         var output = Files.newOutputStream(target);
         var logger = Files.newBufferedWriter(logFile)) {

        input.transferTo(output);
        logger.write("Copied " + source + " to " + target);
    }  // Closes logger, then output, then input - even if exception occurs
}

// Single-byte read - INEFFICIENT, avoid in production
public int countBytes(Path file) throws IOException {
    int count = 0;
    try (var input = Files.newInputStream(file)) {
        int b;
        while ((b = input.read()) != -1) {  // returns int 0-255, or -1
            count++;
        }
    }
    return count;  // thousands of disk I/O operations!
}

// Bulk read with byte array - EFFICIENT
public void copyFile(Path source, Path target) throws IOException {
    try (var input = Files.newInputStream(source);
         var output = Files.newOutputStream(target)) {

        var buffer = new byte[8192];  // 8KB buffer
        int bytesRead;
        while ((bytesRead = input.read(buffer)) != -1) {
            output.write(buffer, 0, bytesRead);  // write only bytes actually read
        }
    }
}

// BufferedReader for text line-by-line
public List<String> readLogFile(Path logFile) throws IOException {
    var lines = new ArrayList<String>();
    try (var reader = Files.newBufferedReader(logFile)) {
        String line;
        while ((line = reader.readLine()) != null) {
            lines.add(line);
        }
    }
    return lines;
}

